const ImportedAdhkarDB = {"azkari_1": [{"id": 10001, "text": "الحمد لله وحده ، والصلاة والسلام على من لا نبي بعده .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al7mdo_llah_part.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10002, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ }", "count": 1, "reference": "سورة البقرة - الآية 255 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_5.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10003, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُن لَّهُ كُفُواً أَحَد } \n بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ * وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ } \n بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ * مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ }", "count": 3, "reference": "سورة الاخلاص وسورة الفلق وسورة الناس .", "times": "3 مرة", "audio": "assets/audio/azkari/alm3wzat_part.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10004, "text": "أَصْـبَحْنا وَأَصْـبَحَ المُـلْكُ لله وَالحَمدُ لله ، لا إلهَ إلاّ اللّهُ وَحدَهُ لا شَريكَ لهُ ، لهُ المُـلكُ ولهُ الحَمْـد ، وهُوَ على كلّ شَيءٍ قدير ، رَبِّ أسْـأَلُـكَ خَـيرَ ما في هـذا اليوم وَخَـيرَ ما بَعْـدَه ، وَأَعـوذُ بِكَ مِنْ شَـرِّ ما في هـذا اليوم وَشَرِّ ما بَعْـدَه ، رَبِّ أَعـوذُبِكَ مِنَ الْكَسَـلِ وَسـوءِ الْكِـبَر ، رَبِّ أَعـوذُبِكَ مِنْ عَـذابٍ في النّـارِ وَعَـذابٍ في القَـبْر .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_1.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10005, "text": "اللّهُـمَّ بِكَ أَصْـبَحْنا ، وَبِكَ أَمْسَـينا ، وَبِكَ نَحْـيا ، وَبِكَ نَمـوتُ وَإِلَـيْكَ النِّـشور .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_2.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10006, "text": "اللّهـمَّ أَنْتَ رَبِّـي لا إلهَ إلاّ أَنْتَ ، خَلَقْتَنـي وَأَنا عَبْـدُك ، وَأَنا عَلـى عَهْـدِكَ وَوَعْـدِكَ ما اسْتَـطَعْـت ، أَعـوذُبِكَ مِنْ شَـرِّ ما صَنَـعْت ، أَبـوءُ لَـكَ بِنِعْـمَتِـكَ عَلَـيَّ وَأَبـوءُ بِذَنْـبي فَاغْفـِرْ لي فَإِنَّـهُ لا يَغْـفِرُ الذُّنـوبَ إِلاّ أَنْتَ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_3.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10007, "text": "اللّهُـمَّ إِنِّـي أَصْبَـحْتُ أَُشْـهِدُك ، وَأُشْـهِدُ حَمَلَـةَ عَـرْشِـك ، وَمَلائِكَتِك ، وَجَمـيعَ خَلْـقِك ، أَنَّـكَ أَنْـتَ اللهُ لا إلهَ إلاّ أَنْـتَ وَحْـدَكَ لا شَريكَ لَـك ، وَأَنَّ ُ مُحَمّـداً عَبْـدُكَ وَرَسـولُـك .", "count": 4, "reference": "من أذكار المسلم", "times": "4 مرة", "audio": "assets/audio/azkari/s_4.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10008, "text": "اللّهُـمَّ ما أَصْبَـَحَ بي مِـنْ نِعْـمَةٍ أَو بِأَحَـدٍ مِـنْ خَلْـقِك ، فَمِـنْكَ وَحْـدَكَ لا شريكَ لَـك ، فَلَـكَ الْحَمْـدُ وَلَـكَ الشُّكْـر .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_5.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10009, "text": "اللّهُـمَّ عافِـني في بَدَنـي ، اللّهُـمَّ عافِـني في سَمْـعي ، اللّهُـمَّ عافِـني في بَصَـري ، لا إلهَ إلاّ أَنْـتَ ، اللّهُـمَّ إِنّـي أَعـوذُبِكَ مِنَ الْكُـفر ، وَالفَـقْر ، وَأَعـوذُبِكَ مِنْ عَذابِ القَـبْر ، لا إلهَ إلاّ أَنْـتَ .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/s_6.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10010, "text": "حَسْبِـيَ اللّهُ لا إلهَ إلاّ هُوَ عَلَـيهِ تَوَكَّـلتُ وَهُوَ رَبُّ العَرْشِ العَظـيم .", "count": 7, "reference": "من أذكار المسلم", "times": "7 مرة", "audio": "assets/audio/azkari/s_7.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10011, "text": "اللّهُـمَّ إِنِّـي أسْـأَلُـكَ العَـفْوَ وَالعـافِـيةَ في الدُّنْـيا وَالآخِـرَة ، اللّهُـمَّ إِنِّـي أسْـأَلُـكَ العَـفْوَ وَالعـافِـيةَ في ديني وَدُنْـيايَ وَأهْـلي وَمالـي ، اللّهُـمَّ اسْتُـرْ عـوْراتي وَآمِـنْ رَوْعاتـي ، اللّهُـمَّ احْفَظْـني مِن بَـينِ يَدَيَّ وَمِن خَلْفـي وَعَن يَمـيني وَعَن شِمـالي ، وَمِن فَوْقـي ، وَأَعـوذُ بِعَظَمَـتِكَ أَن أُغْـتالَ مِن تَحْتـي .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_8.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10012, "text": "اللّهُـمَّ عالِـمَ الغَـيْبِ وَالشّـهادَةِ فاطِـرَ السّماواتِ وَالأرْضِ رَبَّ كـلِّ شَـيءٍ وَمَليـكَه ، أَشْهَـدُ أَنْ لا إِلـهَ إِلاّ أَنْت ، أَعـوذُ بِكَ مِن شَـرِّ نَفْسـي وَمِن شَـرِّ الشَّيْـطانِ وَشِـرْكِه ، وَأَنْ أَقْتَـرِفَ عَلـى نَفْسـي سوءاً أَوْ أَجُـرَّهُ إِلـى مُسْـلِم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_9.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10013, "text": "بِسـمِ اللهِ الذي لا يَضُـرُّ مَعَ اسمِـهِ شَيءٌ في الأرْضِ وَلا في السّمـاءِ وَهـوَ السّمـيعُ العَلـيم .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/s_10.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10014, "text": "رَضيـتُ بِاللهِ رَبَّـاً وَبِالإسْلامِ ديـناً وَبِمُحَـمَّدٍ - صلى الله عليه و سلم - نَبِيّـاً .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/s_11.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10015, "text": "يا حَـيُّ يا قَيّـومُ بِـرَحْمَـتِكِ أَسْتَـغـيث ، أَصْلِـحْ لي شَـأْنـي كُلَّـه ، وَلا تَكِلـني إِلى نَفْـسي طَـرْفَةَ عَـين .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_14.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10016, "text": "أَصْبَـحْـنا وَأَصْبَـحْ المُـلكُ للهِ رَبِّ العـالَمـين ، اللّهُـمَّ إِنِّـي أسْـأَلُـكَ خَـيْرَ هـذا الـيَوْم ، فَـتْحَهُ ، وَنَصْـرَهُ ، وَنـورَهُ وَبَـرَكَتَـهُ ، وَهُـداهُ ، وَأَعـوذُ بِـكَ مِـنْ شَـرِّ ما فـيهِ وَشَـرِّ ما بَعْـدَه .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_16.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10017, "text": "أَصْـبَحْنا علـى فِطْـرَةِ الإسْلام ، وَعَلـى كَلِـمَةِ الإخْـلاص ، وَعلـى دينِ نَبِـيِّنا مُحَـمَّدٍ - صلى الله عليه و سلم - وَعَاـى مِلَّـةِ أبينـا إِبْـراهيـمَ حَنيـفاً مُسْلِـماً وَمـا كـانَ مِنَ المُشـرِكيـن .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_18.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10018, "text": "سبحان الله و بحمده .", "count": 100, "reference": "من أذكار المسلم", "times": "100 مرة", "audio": "assets/audio/azkari/s_13.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10019, "text": "لا إلهَ إلاّ اللّهُ وحْـدَهُ لا شَريكَ لهُ ، لهُ المُلكُ ولهُ الحَمْد ، وهُوَ على كُلّ شَيءٍ قَـدير .", "count": 100, "reference": "من أذكار المسلم", "times": "100 مرة", "audio": "assets/audio/azkari/s_15.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10020, "text": "سُبْحـانَ اللهِ وَبِحَمْـدِهِ عَدَدَ خَلْـقِه ، وَرِضـا نَفْسِـه ، وَزِنَـةَ عَـرْشِـه ، وَمِـدادَ كَلِمـاتِـه .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/s_12.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10021, "text": "اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا , وَرِزْقًا طَيِّبًا , وَعَمَلا مُتَقَبَّلا .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/allah_eny_asalok.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10022, "text": "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ .", "count": 100, "reference": "من أذكار المسلم", "times": "100 مرة", "audio": "assets/audio/azkari/astagfer_allah.mp3", "sourceCategory": "أذكار الصباح"}, {"id": 10023, "text": "اللَّهُمَّ صَلِّ وَسَلِّمْ على نَبِيِّنَا مُحمَّد .", "count": 10, "reference": "من أذكار المسلم", "times": "10 مرة", "audio": "assets/audio/azkari/allahom_saly.mp3", "sourceCategory": "أذكار الصباح"}], "azkari_2": [{"id": 10024, "text": "الحمد لله وحده ، والصلاة والسلام على من لا نبي بعده .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al7mdo_llah_part.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10025, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ }", "count": 1, "reference": "سورة البقرة - الآية 255 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_5.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10026, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُن لَّهُ كُفُواً أَحَد } \n بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ * وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ } \n بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ * مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ }", "count": 3, "reference": "سورة الاخلاص وسورة الفلق وسورة الناس .", "times": "3 مرة", "audio": "assets/audio/azkari/alm3wzat_part.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10027, "text": "أَمْسَيْـنا وَأَمْسـى المـلكُ لله وَالحَمدُ لله ، لا إلهَ إلاّ اللّهُ وَحدَهُ لا شَريكَ لهُ ، لهُ المُـلكُ ولهُ الحَمْـد ، وهُوَ على كلّ شَيءٍ قدير ، رَبِّ أسْـأَلُـكَ خَـيرَ ما في هـذهِ اللَّـيْلَةِ وَخَـيرَ ما بَعْـدَهـا ، وَأَعـوذُ بِكَ مِنْ شَـرِّ ما في هـذهِ اللَّـيْلةِ وَشَرِّ ما بَعْـدَهـا ، رَبِّ أَعـوذُبِكَ مِنَ الْكَسَـلِ وَسـوءِ الْكِـبَر ، رَبِّ أَعـوذُبِكَ مِنْ عَـذابٍ في النّـارِ وَعَـذابٍ في القَـبْر .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/masaa_1.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10028, "text": "اللّهُـمَّ بِكَ أَمْسَـينا ، وَبِكَ أَصْـبَحْنا ، وَبِكَ نَحْـيا ، وَبِكَ نَمـوتُ وَإِلَـيْكَ المَصـير .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/adkaralmsa_2.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10029, "text": "اللّهـمَّ أَنْتَ رَبِّـي لا إلهَ إلاّ أَنْتَ ، خَلَقْتَنـي وَأَنا عَبْـدُك ، وَأَنا عَلـى عَهْـدِكَ وَوَعْـدِكَ ما اسْتَـطَعْـت ، أَعـوذُبِكَ مِنْ شَـرِّ ما صَنَـعْت ، أَبـوءُ لَـكَ بِنِعْـمَتِـكَ عَلَـيَّ وَأَبـوءُ بِذَنْـبي فَاغْفـِرْ لي فَإِنَّـهُ لا يَغْـفِرُ الذُّنـوبَ إِلاّ أَنْتَ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_3.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10030, "text": "اللّهُـمَّ إِنِّـي أَمسيتُ أَشْـهِدُك ، وَأُشْـهِدُ حَمَلَـةَ عَـرْشِـك ، وَمَلائِكَتِك ، وَجَمـيعَ خَلْـقِك ، أَنَّـكَ أَنْـتَ اللهُ لا إلهَ إلاّ أَنْـتَ وَحْـدَكَ لا شَريكَ لَـك ، وَأَنَّ مُحَمّـداً عَبْـدُكَ وَرَسـولُـك .", "count": 4, "reference": "من أذكار المسلم", "times": "4 مرة", "audio": "assets/audio/azkari/masaa_4.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10031, "text": "اللّهُـمَّ ما أَمسى بي مِـنْ نِعْـمَةٍ أَو بِأَحَـدٍ مِـنْ خَلْـقِك ، فَمِـنْكَ وَحْـدَكَ لا شريكَ لَـك ، فَلَـكَ الْحَمْـدُ وَلَـكَ الشُّكْـر .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/masaa_5.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10032, "text": "اللّهُـمَّ عافِـني في بَدَنـي ، اللّهُـمَّ عافِـني في سَمْـعي ، اللّهُـمَّ عافِـني في بَصَـري ، لا إلهَ إلاّ أَنْـتَ ، اللّهُـمَّ إِنّـي أَعـوذُبِكَ مِنَ الْكُـفر ، وَالفَـقْر ، وَأَعـوذُبِكَ مِنْ عَذابِ القَـبْر ، لا إلهَ إلاّ أَنْـتَ .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/s_6.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10033, "text": "حَسْبِـيَ اللّهُ لا إلهَ إلاّ هُوَ عَلَـيهِ تَوَكَّـلتُ وَهُوَ رَبُّ العَرْشِ العَظـيم .", "count": 7, "reference": "من أذكار المسلم", "times": "7 مرة", "audio": "assets/audio/azkari/s_7.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10034, "text": "اللّهُـمَّ إِنِّـي أسْـأَلُـكَ العَـفْوَ وَالعـافِـيةَ في الدُّنْـيا وَالآخِـرَة ، اللّهُـمَّ إِنِّـي أسْـأَلُـكَ العَـفْوَ وَالعـافِـيةَ في ديني وَدُنْـيايَ وَأهْـلي وَمالـي ، اللّهُـمَّ اسْتُـرْ عـوْراتي وَآمِـنْ رَوْعاتـي ، اللّهُـمَّ احْفَظْـني مِن بَـينِ يَدَيَّ وَمِن خَلْفـي وَعَن يَمـيني وَعَن شِمـالي ، وَمِن فَوْقـي ، وَأَعـوذُ بِعَظَمَـتِكَ أَن أُغْـتالَ مِن تَحْتـي .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_8.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10035, "text": "اللّهُـمَّ عالِـمَ الغَـيْبِ وَالشّـهادَةِ فاطِـرَ السّماواتِ وَالأرْضِ رَبَّ كـلِّ شَـيءٍ وَمَليـكَه ، أَشْهَـدُ أَنْ لا إِلـهَ إِلاّ أَنْت ، أَعـوذُ بِكَ مِن شَـرِّ نَفْسـي وَمِن شَـرِّ الشَّيْـطانِ وَشِـرْكِه ، وَأَنْ أَقْتَـرِفَ عَلـى نَفْسـي سوءاً أَوْ أَجُـرَّهُ إِلـى مُسْـلِم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_9.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10036, "text": "بِسـمِ اللهِ الذي لا يَضُـرُّ مَعَ اسمِـهِ شَيءٌ في الأرْضِ وَلا في السّمـاءِ وَهـوَ السّمـيعُ العَلـيم .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/s_10.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10037, "text": "رَضيـتُ بِاللهِ رَبَّـاً وَبِالإسْلامِ ديـناً وَبِمُحَـمَّدٍ - صلى الله عليه و سلم - نَبِيّـاً .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/s_11.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10038, "text": "يا حَـيُّ يا قَيّـومُ بِـرَحْمَـتِكِ أَسْتَـغـيث ، أَصْلِـحْ لي شَـأْنـي كُلَّـه ، وَلا تَكِلـني إِلى نَفْـسي طَـرْفَةَ عَـين .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/s_14.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10039, "text": "أَمْسَيْـنا وَأَمْسـى المُـلكُ للهِ رَبِّ العـالَمـين ، اللّهُـمَّ إِنِّـي أسْـأَلُـكَ خَـيْرَ هـذهِ اللَّـيْلَة ، فَتْحَهـا ، وَنَصْـرَهـا ، وَنـورَهـا وَبَـرَكَتَـهـا ، وَهُـداهـا ، وَأَعـوذُ بِـكَ مِـنْ شَـرِّ ما فـيهـاِ وَشَـرِّ ما بَعْـدَهـا .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_17_part.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10040, "text": "أَمسينا علـى فِطْـرَةِ الإسْلام ، وَعَلـى كَلِـمَةِ الإخْـلاص ، وَعلـى دينِ نَبِـيِّنا مُحَـمَّدٍ - صلى الله عليه و سلم - وَعَاـى مِلَّـةِ أبينـا إِبْـراهيـمَ حَنيـفاً مُسْلِـماً وَمـا كـانَ مِنَ المُشـرِكيـن .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_19_part.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10041, "text": "سبحان الله و بحمده .", "count": 100, "reference": "من أذكار المسلم", "times": "100 مرة", "audio": "assets/audio/azkari/s_13.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10042, "text": "لا إلهَ إلاّ اللّهُ وحْـدَهُ لا شَريكَ لهُ ، لهُ المُلكُ ولهُ الحَمْد ، وهُوَ على كُلّ شَيءٍ قَـدير .", "count": 10, "reference": "من أذكار المسلم", "times": "10 مرة", "audio": "assets/audio/azkari/s_15.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10043, "text": "أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ .", "count": 100, "reference": "من أذكار المسلم", "times": "100 مرة", "audio": "assets/audio/azkari/astagfer_allah.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10044, "text": "أَعـوذُ بِكَلِمـاتِ اللّهِ التّـامّـاتِ مِنْ شَـرِّ ما خَلَـق .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/sound_8_part.mp3", "sourceCategory": "أذكار المساء"}, {"id": 10045, "text": "اللَّهُمَّ صَلِّ وَسَلِّمْ على نَبِيِّنَا مُحمَّد .", "count": 10, "reference": "من أذكار المسلم", "times": "10 مرة", "audio": "assets/audio/azkari/allahom_saly.mp3", "sourceCategory": "أذكار المساء"}], "azkari_3": [{"id": 10046, "text": "اللّهُـمَّ باعِـدْ بَيـني وَبَيْنَ خَطـايايَ كَما باعَدْتَ بَيْنَ المَشْرِقِ وَالمَغْرِبْ ، اللّهُـمَّ نَقِّنـي مِنْ خَطايايَ كَمـا يُـنَقَّى الثَّـوْبُ الأَبْيَضُ مِنَ الدَّنَسْ ، اللّهُـمَّ اغْسِلْنـي مِنْ خَطايـايَ بِالثَّلـجِ وَالمـاءِ وَالْبَرَدْ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_before_1.mp3", "sourceCategory": "دعاء الاستفتاح"}, {"id": 10047, "text": "سُبْـحانَكَ اللّهُـمَّ وَبِحَمْـدِكَ وَتَبارَكَ اسْمُـكَ وَتَعـالى جَـدُّكَ وَلا إِلهَ غَيْرُك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_before_2.mp3", "sourceCategory": "دعاء الاستفتاح"}, {"id": 10048, "text": "وَجَّهـتُ وَجْهِـيَ لِلَّذي فَطَرَ السَّمـواتِ وَالأَرْضَ حَنـيفَاً وَمـا أَنا مِنَ المشْرِكين ، إِنَّ صَلاتـي ، وَنُسُكي ، وَمَحْـيايَ ، وَمَماتـي للهِ رَبِّ العالَمين ، لا شَريـكَ لَهُ وَبِذلكَ أُمِرْتُ وَأَنا مِنَ المسْلِـمين . اللّهُـمَّ أَنْتَ المَلِكُ لا إِلهَ إِلاّ أَنْت ، أَنْتَ رَبِّـي وَأَنـا عَبْـدُك ، ظَلَمْـتُ نَفْسـي وَاعْـتَرَفْتُ بِذَنْبـي فَاغْفِرْ لي ذُنوبي جَميعاً إِنَّـه لا يَغْـفِرُ الذُّنـوبَ إلاّ أَنْت . وَاهْدِنـي لأَحْسَنِ الأَخْلاقِ لا يَهْـدي لأَحْسَـنِها إِلاّ أَنْـت ، وَاصْـرِف عَـنّْي سَيِّئَهـا ، لا يَصْرِفُ عَـنّْي سَيِّئَهـا إِلاّ أَنْـت ، لَبَّـيْكَ وَسَعْـدَيْك ، وَالخَـيْرُ كُلُّـهُ بِيَـدَيْـك ، وَالشَّرُّ لَيْـسَ إِلَـيْك ، أَنا بِكَ وَإِلَيْـك ، تَبـارَكْتَ وَتَعـالَيتَ أَسْتَغْـفِرُكَ وَأَتوبُ إِلَـيك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_before_3.mp3", "sourceCategory": "دعاء الاستفتاح"}, {"id": 10049, "text": "اللّهُـمَّ رَبَّ جِـبْرائيل ، وَميكـائيل ، وَإِسْـرافيل ، فاطِـرَ السَّمواتِ وَالأَرْض ، عالـِمَ الغَيْـبِ وَالشَّهـادَةِ أَنْـتَ تَحْـكمُ بَيْـنَ عِبـادِكَ فيـما كانوا فيهِ يَخْتَلِفـون . اهدِنـي لِمـا اخْتُـلِفَ فيـهِ مِنَ الْحَـقِّ بِإِذْنِك ، إِنَّـكَ تَهْـدي مَنْ تَشـاءُ إِلى صِراطٍ مُسْتَقـيم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_before_4.mp3", "sourceCategory": "دعاء الاستفتاح"}, {"id": 10050, "text": "اللهُ أَكْبَـرُ كَبـيرا ، اللهُ أَكْبَـرُ كَبـيرا ، اللهُ أَكْبَـرُ كَبـيرا ، وَالْحَـمْدُ للهِ كَثـيرا ، وَالْحَـمْدُ للهِ كَثـيرا ، وَالْحَـمْدُ للهِ كَثـيرا ، وَسُبْـحانَ اللهِ بكْـرَةً وَأَصيـلا .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/salah_before_5.mp3", "sourceCategory": "دعاء الاستفتاح"}, {"id": 10051, "text": "أَعـوذُ بِاللهِ مِنَ الشَّـيْطانِ مِنْ نَفْخِـهِ وَنَفْـثِهِ وَهَمْـزِه .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_before_6.mp3", "sourceCategory": "دعاء الاستفتاح"}, {"id": 10052, "text": "اللّهُـمَّ لَكَ الْحَمْدُ أَنْتَ نـورُ السَّمـواتِ وَالأَرْضِ وَمَنْ فيـهِن ، وَلَكَ الْحَمْدُ أَنْتَ قَـيِّمُ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن ، وَلَكَ الْحَمْدُ أَنْتَ رَبُّ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن ، وَلَكَ الْحَمْدُ لَكَ مُلْـكُ السَّـمواتِ وَالأَرْضِ وَمَنْ فيـهِن ، وَلَكَ الْحَمْدُ أَنْتَ مَلِـكُ السَّـمواتِ وَالأَرْضِ ، وَلَكَ الْحَمْدُ ، أَنْتَ الْحَـقّ وَوَعْـدُكَ الْحَـق ، وَقَوْلُـكَ الْحَـق ، وَلِقـاؤُكَ الْحَـق ، وَالْجَـنَّةُحَـق ، وَالنّـارُ حَـق ، وَالنَّبِـيّونَ حَـق ، وَمـحَمَّدٌ - صلى الله عليه و سلم - حَـق ، وَالسّـاعَة ُحَـق ، اللّهُـمَّ لَكَ أَسْلَمت ، وَعَلَـيْكَ تَوَكَّلْـت ، وَبِكَ آمَنْـت ، وَإِلَـيْكَ أَنَبْـت ، وَبِـكَ خاصَمْت ، وَإِلَـيْكَ حاكَمْـت . فاغْفِـرْ لي مـا قَدَّمْتُ ، وَما أَخَّـرْت ، وَما أَسْـرَرْت ، وَما أَعْلَـنْت ، أَنْتَ المُقَـدِّمُ وَأَنْتَ المُـؤَخِّر ، لا إِاـهَ إِلاّ أَنْـت ، أَنْـتَ إِلـهي لا إِاـهَ إِلاّ أَنْـت .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_before_7.mp3", "sourceCategory": "دعاء الاستفتاح"}], "azkari_4": [{"id": 10053, "text": "أَسْـتَغْفِرُ الله .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/salah_after_1.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10054, "text": "اللّهُـمَّ أَنْـتَ السَّلامُ ، وَمِـنْكَ السَّلام ، تَبارَكْتَ يا ذا الجَـلالِ وَالإِكْـرام .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_2.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10055, "text": "لا إلهَ إلاّ اللّهُ وحدَهُ لا شريكَ لهُ ، لهُ المُـلْكُ ولهُ الحَمْد ، وهوَ على كلّ شَيءٍ قَدير ، اللّهُـمَّ لا مانِعَ لِما أَعْطَـيْت ، وَلا مُعْطِـيَ لِما مَنَـعْت ، وَلا يَنْفَـعُ ذا الجَـدِّ مِنْـكَ الجَـد .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_3.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10056, "text": "لا إلهَ إلاّ اللّه, وحدَهُ لا شريكَ لهُ ، لهُ الملكُ ولهُ الحَمد ، وهوَ على كلّ شيءٍ قدير ، لا حَـوْلَ وَلا قـوَّةَ إِلاّ بِاللهِ ، لا إلهَ إلاّ اللّـه ، وَلا نَعْـبُـدُ إِلاّ إيّـاه ، لَهُ النِّعْـمَةُ وَلَهُ الفَضْل وَلَهُ الثَّـناءُ الحَـسَن ، لا إلهَ إلاّ اللّهُ مخْلِصـينَ لَـهُ الدِّينَ وَلَوْ كَـرِهَ الكـافِرون .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_4.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10057, "text": "سُـبْحانَ اللهِ ، والحَمْـدُ لله ، واللهُ أكْـبَر .", "count": 33, "reference": "من أذكار المسلم", "times": "33 مرة", "audio": "assets/audio/azkari/salah_after_5.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10058, "text": "لا إلهَ إلاّ اللّهُ وَحْـدَهُ لا شريكَ لهُ ، لهُ الملكُ ولهُ الحَمْد ، وهُوَ على كُلّ شَيءٍ قَـدير .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_6.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10059, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُن لَّهُ كُفُواً أَحَد }", "count": 1, "reference": "سورة الاخلاص .", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_7.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10060, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ * وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ }", "count": 1, "reference": "سورة الفلق .", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_8.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10061, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ * مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ }", "count": 1, "reference": "سورة الناس .", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_9.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10062, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ }", "count": 1, "reference": "سورة البقرة - الآية 255 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_10.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10063, "text": "لا إلهَ إلاّ اللّهُ وحْـدَهُ لا شريكَ لهُ ، لهُ المُلكُ ولهُ الحَمْد ، يُحيـي وَيُمـيتُ وهُوَ على كُلّ شيءٍ قدير . ( عَشْر مَرّات بَعْدَ المَغْرِب وَالصّـبْح )", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_11.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}, {"id": 10064, "text": "اللّهُـمَّ إِنِّـي أَسْأَلُـكَ عِلْمـاً نافِعـاً وَرِزْقـاً طَيِّـباً ، وَعَمَـلاً مُتَقَـبَّلاً . ( بَعْد السّلامِ من صَلاةِ الفَجْر )", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/salah_after_12.mp3", "sourceCategory": "أذكار ما بعد الصلاة"}], "azkari_5": [{"id": 10065, "text": "يجمع كفيه ثم ينفث فيهما فيقرأ : بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُن لَّهُ كُفُواً أَحَد } بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِن شَرِّ مَا خَلَقَ * وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ * وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ } بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ * مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ * مِنَ الْجِنَّةِ وَالنَّاسِ } ثم يمسح بهما ما استطاع من جسده يبدأبهما على رأسه ووجهه وما أقبل من جسده .", "count": 3, "reference": "سورة الاخلاص وسورة الفلق وسورة الناس .", "times": "3 مرة", "audio": "assets/audio/azkari/al_nawm_1.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10066, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { اللّهُ لاَ إِلَـهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لاَ تَأْخُذُهُ سِنَةٌ وَلاَ نَوْمٌ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ مَن ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلاَ يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلاَّ بِمَا شَاء وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ }", "count": 1, "reference": "سورة البقرة - الآية 255 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_2.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10067, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللّهِ وَمَلآئِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لاَ نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ وَقَالُواْ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ * لاَ يُكَلِّفُ اللّهُ نَفْساً إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْراً كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ }", "count": 1, "reference": "سورة البقرة - الآية 285 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_3.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10068, "text": "بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي ، وَبِكَ أَرْفَعُهُ ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا ، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_4.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10069, "text": "اللّهُـمَّ إِنَّـكَ خَلَـقْتَ نَفْسـي وَأَنْـتَ تَوَفّـاهـا ، لَكَ ممَـاتـها وَمَحْـياها ، إِنْ أَحْيَيْـتَها فاحْفَظْـها ، وَإِنْ أَمَتَّـها فَاغْفِـرْ لَـها . اللّهُـمَّ إِنَّـي أَسْـأَلُـكَ العـافِـيَة .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_5.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10070, "text": "اللّهُـمَّ قِنـي عَذابَـكَ يَـوْمَ تَبْـعَثُ عِبـادَك .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/al_nawm_6.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10071, "text": "بِاسْـمِكَ اللّهُـمَّ أَمـوتُ وَأَحْـيا .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_7.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10072, "text": "سبحان الله .", "count": 33, "reference": "من أذكار المسلم", "times": "33 مرة", "audio": "assets/audio/azkari/al_nawm_8.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10073, "text": "الحمد لله .", "count": 33, "reference": "من أذكار المسلم", "times": "33 مرة", "audio": "assets/audio/azkari/al_nawm_9.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10074, "text": "الله أكبر .", "count": 34, "reference": "من أذكار المسلم", "times": "34 مرة", "audio": "assets/audio/azkari/al_nawm_10.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10075, "text": "اللهم ربَّ السموات السبع ، ورب العرش العظيم ، ربنا ورب كل شيء ، فالق الحب والنوى ، ومُنزل التوراة والإنجيل والفرقان ، أعوذ بك من شر كل شيء أنت آخذٌ بناصيته ، اللهم أنت الأول فليس قبلك شيء ، وأنت الآخر فليس بعدك شيء ، وأنت الظاهر فليس فوقك شيء ، وأنت الباطن فليس دونك شيء ، اقض عنا الدَّيْنَ واغننا من الفقر .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_11.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10076, "text": "الـحَمْدُ للهِ الَّذي أَطْـعَمَنا وَسَقـانا ، وَكَفـانا ، وَآوانا ، فَكَـمْ مِمَّـنْ لا كـافِيَ لَـهُ وَلا مُـؤْوي .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_12_1.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10077, "text": "اللهم عالم الغيب والشهادة ، فاطر السموات والأرض ، رب كل شيء ومليكه أشهد أن لا إله إلا أنت أعوذ بك من شر نفسي ، ومن شر الشيطان وشركه وأن أقترف على نفسي سوءًا أو أجرَّه إلى مسلم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_12_2.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10078, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { الم * تَنْزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِنْ رَبِّ الْعَالَمِينَ * أَمْ يَقُولُونَ افْتَرَاهُ بَلْ هُوَ الْحَقُّ مِنْ رَبِّكَ لِتُنْذِرَ قَوْمًا مَا أَتَاهُمْ مِنْ نَذِيرٍ مِنْ قَبْلِكَ لَعَلَّهُمْ يَهْتَدُونَ * اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ مَا لَكُمْ مِنْ دُونِهِ مِنْ وَلِيٍّ وَلَا شَفِيعٍ أَفَلَا تَتَذَكَّرُونَ * يُدَبِّرُ الْأَمْرَ مِنَ السَّمَاءِ إِلَى الْأَرْضِ ثُمَّ يَعْرُجُ إِلَيْهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ أَلْفَ سَنَةٍ مِمَّا تَعُدُّونَ * ذَلِكَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْعَزِيزُ الرَّحِيمُ * الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ وَبَدَأَ خَلْقَ الْإِنْسَانِ مِنْ طِينٍ * ثُمَّ جَعَلَ نَسْلَهُ مِنْ سُلَالَةٍ مِنْ مَاءٍ مَهِينٍ * ثُمَّ سَوَّاهُ وَنَفَخَ فِيهِ مِنْ رُوحِهِ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَا تَشْكُرُونَ * وَقَالُوا أَئِذَا ضَلَلْنَا فِي الْأَرْضِ أَئِنَّا لَفِي خَلْقٍ جَدِيدٍ بَلْ هُمْ بِلِقَاءِ رَبِّهِمْ كَافِرُونَ * قُلْ يَتَوَفَّاكُمْ مَلَكُ الْمَوْتِ الَّذِي وُكِّلَ بِكُمْ ثُمَّ إِلَى رَبِّكُمْ تُرْجَعُونَ * وَلَوْ تَرَى إِذِ الْمُجْرِمُونَ نَاكِسُوا رُءُوسِهِمْ عِنْدَ رَبِّهِمْ رَبَّنَا أَبْصَرْنَا وَسَمِعْنَا فَارْجِعْنَا نَعْمَلْ صَالِحًا إِنَّا مُوقِنُونَ * وَلَوْ شِئْنَا لَآَتَيْنَا كُلَّ نَفْسٍ هُدَاهَا وَلَكِنْ حَقَّ الْقَوْلُ مِنِّي لَأَمْلَأَنَّ جَهَنَّمَ مِنَ الْجِنَّةِ وَالنَّاسِ أَجْمَعِينَ * فَذُوقُوا بِمَا نَسِيتُمْ لِقَاءَ يَوْمِكُمْ هَذَا إِنَّا نَسِينَاكُمْ وَذُوقُوا عَذَابَ الْخُلْدِ بِمَا كُنْتُمْ تَعْمَلُونَ * إِنَّمَا يُؤْمِنُ بِآَيَاتِنَا الَّذِينَ إِذَا ذُكِّرُوا بِهَا خَرُّوا سُجَّدًا وَسَبَّحُوا بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ * تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ * فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ * أَفَمَنْ كَانَ مُؤْمِنًا كَمَنْ كَانَ فَاسِقًا لَا يَسْتَوُونَ * أَمَّا الَّذِينَ آَمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَلَهُمْ جَنَّاتُ الْمَأْوَى نُزُلًا بِمَا كَانُوا يَعْمَلُونَ * وَأَمَّا الَّذِينَ فَسَقُوا فَمَأْوَاهُمُ النَّارُ كُلَّمَا أَرَادُوا أَنْ يَخْرُجُوا مِنْهَا أُعِيدُوا فِيهَا وَقِيلَ لَهُمْ ذُوقُوا عَذَابَ النَّارِ الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ * وَلَنُذِيقَنَّهُمْ مِنَ الْعَذَابِ الْأَدْنَى دُونَ الْعَذَابِ الْأَكْبَرِ لَعَلَّهُمْ يَرْجِعُونَ * وَمَنْ أَظْلَمُ مِمَّنْ ذُكِّرَ بِآَيَاتِ رَبِّهِ ثُمَّ أَعْرَضَ عَنْهَا إِنَّا مِنَ الْمُجْرِمِينَ مُنْتَقِمُونَ * وَلَقَدْ آَتَيْنَا مُوسَى الْكِتَابَ فَلَا تَكُنْ فِي مِرْيَةٍ مِنْ لِقَائِهِ وَجَعَلْنَاهُ هُدًى لِبَنِي إِسْرَائِيلَ * وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآَيَاتِنَا يُوقِنُونَ * إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ * أَوَلَمْ يَهْدِ لَهُمْ كَمْ أَهْلَكْنَا مِنْ قَبْلِهِمْ مِنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآَيَاتٍ أَفَلَا يَسْمَعُونَ * أَوَلَمْ يَرَوْا أَنَّا نَسُوقُ الْمَاءَ إِلَى الْأَرْضِ الْجُرُزِ فَنُخْرِجُ بِهِ زَرْعًا تَأْكُلُ مِنْهُ أَنْعَامُهُمْ وَأَنْفُسُهُمْ أَفَلَا يُبْصِرُونَ * وَيَقُولُونَ مَتَى هَذَا الْفَتْحُ إِنْ كُنْتُمْ صَادِقِينَ * قُلْ يَوْمَ الْفَتْحِ لَا يَنْفَعُ الَّذِينَ كَفَرُوا إِيمَانُهُمْ وَلَا هُمْ يُنْظَرُونَ * فَأَعْرِضْ عَنْهُمْ وَانْتَظِرْ إِنَّهُمْ مُنْتَظِرُونَ }", "count": 1, "reference": "سورة السجدة .", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_sajda.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10079, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ * الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا وَهُوَ الْعَزِيزُ الْغَفُورُ * الَّذِي خَلَقَ سَبْعَ سَمَوَاتٍ طِبَاقًا مَا تَرَى فِي خَلْقِ الرَّحْمَنِ مِنْ تَفَاوُتٍ فَارْجِعِ الْبَصَرَ هَلْ تَرَى مِنْ فُطُورٍ * ثُمَّ ارْجِعِ الْبَصَرَ كَرَّتَيْنِ يَنْقَلِبْ إِلَيْكَ الْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ * وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَجَعَلْنَاهَا رُجُومًا لِلشَّيَاطِينِ وَأَعْتَدْنَا لَهُمْ عَذَابَ السَّعِيرِ * وَلِلَّذِينَ كَفَرُوا بِرَبِّهِمْ عَذَابُ جَهَنَّمَ وَبِئْسَ الْمَصِيرُ * إِذَا أُلْقُوا فِيهَا سَمِعُوا لَهَا شَهِيقًا وَهِيَ تَفُورُ * تَكَادُ تَمَيَّزُ مِنَ الْغَيْظِ كُلَّمَا أُلْقِيَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَا أَلَمْ يَأْتِكُمْ نَذِيرٌ * قَالُوا بَلَى قَدْ جَاءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ اللَّهُ مِنْ شَيْءٍ إِنْ أَنْتُمْ إِلَّا فِي ضَلَالٍ كَبِيرٍ * وَقَالُوا لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِي أَصْحَابِ السَّعِيرِ * فَاعْتَرَفُوا بِذَنْبِهِمْ فَسُحْقًا لِأَصْحَابِ السَّعِيرِ * إِنَّ الَّذِينَ يَخْشَوْنَ رَبَّهُمْ بِالْغَيْبِ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ * وَأَسِرُّوا قَوْلَكُمْ أَوِ اجْهَرُوا بِهِ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ * أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ * هُوَ الَّذِي جَعَلَ لَكُمُ الْأَرْضَ ذَلُولًا فَامْشُوا فِي مَنَاكِبِهَا وَكُلُوا مِنْ رِزْقِهِ وَإِلَيْهِ النُّشُورُ * ءَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ فَإِذَا هِيَ تَمُورُ * أَمْ أَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ * وَلَقَدْ كَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ * أَوَلَمْ يَرَوْا إِلَى الطَّيْرِ فَوْقَهُمْ صَافَّاتٍ وَيَقْبِضْنَ مَا يُمْسِكُهُنَّ إِلَّا الرَّحْمَنُ إِنَّهُ بِكُلِّ شَيْءٍ بَصِيرٌ * أَمَّنْ هَذَا الَّذِي هُوَ جُنْدٌ لَكُمْ يَنْصُرُكُمْ مِنْ دُونِ الرَّحْمَنِ إِنِ الْكَافِرُونَ إِلَّا فِي غُرُورٍ * أَمَّنْ هَذَا الَّذِي يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُ بَلْ لَجُّوا فِي عُتُوٍّ وَنُفُورٍ * أَفَمَنْ يَمْشِي مُكِبًّا عَلَى وَجْهِهِ أَهْدَى أَمَّنْ يَمْشِي سَوِيًّا عَلَى صِرَاطٍ مُسْتَقِيمٍ * قُلْ هُوَ الَّذِي أَنْشَأَكُمْ وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَا تَشْكُرُونَ * قُلْ هُوَ الَّذِي ذَرَأَكُمْ فِي الْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ * وَيَقُولُونَ مَتَى هَذَا الْوَعْدُ إِنْ كُنْتُمْ صَادِقِينَ * قُلْ إِنَّمَا الْعِلْمُ عِنْدَ اللَّهِ وَإِنَّمَا أَنَا نَذِيرٌ مُبِينٌ * فَلَمَّا رَأَوْهُ زُلْفَةً سِيئَتْ وُجُوهُ الَّذِينَ كَفَرُوا وَقِيلَ هَذَا الَّذِي كُنْتُمْ بِهِ تَدَّعُونَ * قُلْ أَرَأَيْتُمْ إِنْ أَهْلَكَنِيَ اللَّهُ وَمَنْ مَعِيَ أَوْ رَحِمَنَا فَمَنْ يُجِيرُ الْكَافِرِينَ مِنْ عَذَابٍ أَلِيمٍ * قُلْ هُوَ الرَّحْمَنُ ءآَمَنَّا بِهِ وَعَلَيْهِ تَوَكَّلْنَا فَسَتَعْلَمُونَ مَنْ هُوَ فِي ضَلَالٍ مُبِينٍ * قُلْ أَرَأَيْتُمْ إِنْ أَصْبَحَ مَاؤُكُمْ غَوْرًا فَمَنْ يَأْتِيكُمْ بِمَاءٍ مَعِينٍ }", "count": 1, "reference": "سورة الملك .", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_mulk.mp3", "sourceCategory": "أذكار ما قبل النوم"}, {"id": 10080, "text": "اللهم أسلمت نفسي إليك ، وفوضت أمري إليك وَوجَّهْتُ وَجْهي إلَيْكَ وألجأت ظهري إليك رغبةً ورهبةً إليك ، لا ملجأ ولا منجا منك إلا إليك ، آمنت بكتابك الذي أنزلت وبنبيك الذي أرسلت .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/al_nawm_14.mp3", "sourceCategory": "أذكار ما قبل النوم"}], "azkari_6": [{"id": 10081, "text": "الحَمْدُ لله الذِي أحْيَانا بَعْدَمَا أمَاتَنَا وإلَيْهِ النَشُور .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteqaz_1.mp3", "sourceCategory": "أذكار الاستيقاظ من النوم"}, {"id": 10082, "text": "الحَمْدُ لله الذِي عَافَانِي في جَسَدِي ورَدَّ عَلَيَّ رُوحِي ، وأَذِنَ لي بِذِكْرهِ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteqaz_2.mp3", "sourceCategory": "أذكار الاستيقاظ من النوم"}, {"id": 10083, "text": "لا اله الا الله وحده لا شريك له , له الملك وله الحمد , وهو على كل شيء قدير . سبحان الله والحمد لله ولا اله الا الله والله اكبر ولاحول ولاقوة الا بالله العلي العظيم ربي اغفر لي .", "count": 1, "reference": "", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteqaz_3.mp3", "sourceCategory": "أذكار الاستيقاظ من النوم"}, {"id": 10084, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالأَرْضِ وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ لآيَاتٍ لِّأُوْلِي الألْبَابِ * الَّذِينَ يَذْكُرُونَ اللّهَ قِيَاماً وَقُعُوداً وَعَلَىَ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذا بَاطِلاً سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ * َربَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ * رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِياً يُنَادِي لِلإِيمَانِ أَنْ آمِنُواْ بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الأبْرَارِ * رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَى رُسُلِكَ وَلاَ تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لاَ تُخْلِفُ الْمِيعَادَ * َفاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لاَ أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَى بَعْضُكُم مِّن بَعْضٍ فَالَّذِينَ هَاجَرُواْ وَأُخْرِجُواْ مِن دِيَارِهِمْ وَأُوذُواْ فِي سَبِيلِي وَقَاتَلُواْ وَقُتِلُواْ لأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ ثَوَاباً مِّن عِندِ اللّهِ وَاللّهُ عِندَهُ حُسْنُ الثَّوَابِ * لاَ يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُواْ فِي الْبِلاَدِ * مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ * لَكِنِ الَّذِينَ اتَّقَوْاْ رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا نُزُلاً مِّنْ عِندِ اللّهِ وَمَا عِندَ اللّهِ خَيْرٌ لِّلأَبْرَارِ * وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللّهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلّهِ لاَ يَشْتَرُونَ بِآيَاتِ اللّهِ ثَمَناً قَلِيلاً أُوْلَـئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ اللّهَ سَرِيعُ الْحِسَابِ * يَا أَيُّهَا الَّذِينَ آمَنُواْ اصْبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَاتَّقُواْ اللّهَ لَعَلَّكُمْ تُفْلِحُونَ }", "count": 1, "reference": "سورة آل عمران - الآيات 190 - 200 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteqaz_4.mp3", "sourceCategory": "أذكار الاستيقاظ من النوم"}], "azkari_7": [{"id": 10085, "text": "بسم الله . الحمد لله . { سُبْحانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ } الحمد لله ، الحمد لله ، الحمد لله ، الله اكبر ، الله اكبر ، الله اكبر ، سبحانك اللهم إني ظلمت نفسي فاغفر لي ، فإنه لا يغفر الذنوب إلا أنت .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/rokoob.mp3", "sourceCategory": "دعاء الركوب"}], "azkari_8": [{"id": 10086, "text": "الله أكبر ، الله أكبر ، الله أكبر ، { سُبْحانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنقَلِبُونَ } اللهم إنا نسألُكَ في سفرنا هذا البرَّ والتقوى ، ومن العمل ما ترضى ، اللهم هون علينا سفرنا هذا واطو عنا بعده ، اللهم أنت الصاحب في السفر ، والخليفة في الأهل ، اللهم إني أعوذ بك من وعْثاءِ السفر ، وكآبة المنظر وسوء المنقلب في المال والأهل .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/safar.mp3", "sourceCategory": "دعاء السفر"}], "azkari_9": [{"id": 10087, "text": "يكبر على كل شرف ثلاث تكبيرات ثم يقول : لا إله إلا الله وحده لا شريك لهُ ، لهُ الملك ، ولهُ الحمدُ وهو على كل شيءٍ قدير ، آيبون ، تائبون ، عابدون ، لربنا حامدون ، صدق الله وعده ، ونصر عبده ، وهزم الأحزاب وحده .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/rjoo3.mp3", "sourceCategory": "دعاء الرجوع من السفر"}], "azkari_10": [{"id": 10088, "text": "أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إليه .", "count": 100, "reference": "قال صلى الله عليه وسلم : من قال أستغفر الله العظيم الذي لا إله إلا هو الحي القيوم وأتوب إليه ، غفر الله لهُ وإن كان فر من الزحف .", "times": "100 مرة", "audio": "assets/audio/azkari/esteghfar_1.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10089, "text": "سبحان الله وبحمده .", "count": 100, "reference": "قال صلى الله عيه وسلم : من قال سبحان الله وبحمده في يوم مائة مرة حطت خطاياه ولو كانت مثل زبد البحر .", "times": "100 مرة", "audio": "assets/audio/azkari/esteghfar_2.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10090, "text": "لا إله إلا الله وحده لا شريك لهُ ، لهُ الملك ، ولهُ الحمدُ ، وهو على كل شيء قدير .", "count": 100, "reference": "قال صلى الله عيه وسلم : من قال لا إله إلا وحده لا شريك لهُ ، لهُ الملك ، ولهُ الحمدُ ، وهو على كل شيء قدير عشر مرات . كان كمن أعتق أربعة أنفس من ولد إسماعيل وقال صلى الله عيه وسلم : أيعجز أحدكم أن يكسب كل يوم ألف حسنةفسأله سائل من جلسائه كيف يكسب أحدنا ألف حسنة ؟ قال : يسبح مائة تسبيحة ، فيكتب له ألف حسنة أو يحط عنه ُ ألف خطيئة .", "times": "100 مرة", "audio": "assets/audio/azkari/esteghfar_3.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10091, "text": "سبحان الله وبحمده سبحان الله العظيم .", "count": 1, "reference": "قال صلى الله عيه وسلم : كلمتان خفيفتان على اللسان ، ثقيلتان في الميزان حبيبتان إلى الرحمن : سبحان الله وبحمده سبحان الله العظيم .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteghfar_4.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10092, "text": "سبحان الله ، والحمد لله ، ولا إله إلا الله ، والله أكبر .", "count": 1, "reference": "قال صلى الله عيه وسلم : لأن أقول سبحان الله ، والحمد لله ، ولا إله إلا الله ، والله أكبر ، أحب إلى مما طلعت عليه الشمس .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteghfar_5.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10093, "text": "سبحان الله العظيم وبحمده .", "count": 1, "reference": "قال صلى الله عيه وسلم : من قال سبحان الله العظيم وبحمده غرست له نخلة في الجنة .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteghfar_6.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10094, "text": "لا حول ولا قوة إلا بالله .", "count": 1, "reference": "قال صلى الله عيه وسلم : يا عبد الله بن قيس ألا أدلك على كنز من كنوز الجنة ؟ فقلت : بلى يا رسول الله ، قال : قل لا حول ولا قوة إلا بالله .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteghfar_7.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10095, "text": "سبحان الله ، والحمد لله ، ولا إله إلا الله ، والله أكبر .", "count": 1, "reference": "قال صلى الله عيه وسلم : أحب الكلام إلى الله أربعٌ : سبحان الله ، والحمد لله ، ولا إله إلا الله ، والله أكبر ، لا يضرك بأيهنَّ بدأت . و قال صلى الله عيه وسلم : الباقيات الصالحات : سبحان الله والحمد لله ، ولا إله إلا الله ، والله أكبر ، و لا حول ولا قوة إلا بالله .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteghfar_5.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10096, "text": "لا إله إلا الله وحده لا شريك لهً ، الله أكبرُ كبيراً ، والحمد لله كثيراً ، سبحان الله رب العالمين ، لا حول ولا قوة إلا بالله العزيز الحكيم .", "count": 1, "reference": "جاء أعربي إلى رسول الله صلى الله عيه وسلم فقال : علمني كلاماً أقوله : قال قل لا إله إلا الله وحده لا شريك لهً ، الله أكبرُ كبيراً ، والحمد لله كثيراً ، سبحان الله رب العالمين ، لا حول ولا قوة إلا بالله العزيز الحكيم قال فهؤلاء لربي فما لي ؟ قال قل : اللهم اغفر لي ، وارحمني ، واهدني وارزقني .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteghfar_9.mp3", "sourceCategory": "الاستغفار والتوبه"}, {"id": 10097, "text": "اللَّهُمَّ اغْفِرِ لِي ، وارْحَمْنِي ، واهْدِنِي ، وارْزُقْنِي .", "count": 1, "reference": "جاء أعربي إلى رسول الله صلى الله عيه وسلم فقال : علمني كلاماً أقوله : قال قل لا إله إلا الله وحده لا شريك لهً ، الله أكبرُ كبيراً ، والحمد لله كثيراً ، سبحان الله رب العالمين ، لا حول ولا قوة إلا بالله العزيز الحكيم قال فهؤلاء لربي فما لي ؟ قال قل : اللهم اغفر لي ، وارحمني ، واهدني وارزقني .", "times": "مرة واحدة", "audio": "assets/audio/azkari/esteghfar_10.mp3", "sourceCategory": "الاستغفار والتوبه"}], "azkari_11": [{"id": 10098, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ * الرَّحْمَنِ الرَّحِيمِ * مَالِكِ يَوْمِ الدِّينِ * إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ * اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ * صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ و َلَا الضَّالِّين }", "count": 3, "reference": "سورة الفاتحة .", "times": "3 مرة", "audio": "assets/audio/azkari/ruqya_1.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10099, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { الم * ذَلِكَ الْكِتَابُ لَا رَيْبَ فِيهِ هُدًى لِلْمُتَّقِينَ * الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَاةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ * وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنْزِلَ إِلَيْكَ وَمَا أُنْزِلَ مِنْ قَبْلِكَ وَبِالْآَخِرَةِ هُمْ يُوقِنُونَ * أُولَئِكَ عَلَى هُدًى مِنْ رَبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ }", "count": 1, "reference": "سورة البقرة - الآيات 1 - 5 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_2.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10100, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { وَاتَّبَعُوا مَا تَتْلُوا الشَّيَاطِينُ عَلَى مُلْكِ سُلَيْمَانَ وَمَا كَفَرَ سُلَيْمَانُ وَلَكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّى يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ وَمَا هُمْ بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنْفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الْآَخِرَةِ مِنْ خَلَاقٍ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنْفُسَهُمْ لَوْ كَانُوا يَعْلَمُونَ }", "count": 1, "reference": "سورة البقرة - الآية 102 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_3.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10101, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلا هُوَ الرَّحْمَنُ الرَّحِيمُ * إِنَّ فِى خَلْقِ السَّمَاوَاتِ وَالأرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهَارِ وَالْفُلْكِ الَّتِى تَجْرِى فِى الْبَحْرِ بِمَا يَنفَعُ النَّاسَ وَمَا أَنزَلَ اللَّهُ مِنْ السَّمَاءِ مِنْ مَاءٍ فَأَحْيَا بِهِ الأرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِنْ كُلِّ دَابَّةٍ وَتَصْرِيفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالأرْضِ لأيَاتٍ لِقَوْمٍ يَعْقِلُونَ }", "count": 1, "reference": "سورة البقرة - الآيات 163 - 164 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_4.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10102, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { اللَّهُ لا إِلَهَ إِلا هُوَ الْحَىُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ مَا فِى السَّمَاوَاتِ وَمَا فِى الأرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَىْءٍ مِنْ عِلْمِهِ إِلا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِىُّ الْعَظِيمُ }", "count": 3, "reference": "سورة البقرة - الآية 255 .", "times": "3 مرة", "audio": "assets/audio/azkari/ruqya_5.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10103, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { ءامَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ ءامَنَ بِاللَّهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ * لا يُكَلِّفُ اللَّهُ نَفْسًا إِلا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا رَبَّنَا وَلا تُحَمِّلْنَا مَا لا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ }", "count": 3, "reference": "سورة البقرة - الآيات 285 - 286 .", "times": "3 مرة", "audio": "assets/audio/azkari/ruqya_6.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10104, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { شَهِدَ اللَّهُ أَنَّهُ لا إِلَهَ إِلا هُوَ وَالْمَلائِكَةُ وَأُوْلُوا الْعِلْمِ قَائِمًا بِالْقِسْطِ لا إِلَهَ إِلا هُوَ الْعَزِيزُ الْحَكِيمُ * إِنَّ الدِّينَ عِنْدَ اللَّهِ الإسلام وَمَا اخْتَلَفَ الَّذِينَ أُوتُوا الْكِتَابَ إِلا مِنْ بَعْدِ مَا جَاءَهُمْ الْعِلْمُ بَغْيًا بَيْنَهُمْ وَمَنْ يَكْفُرْ بِأيَاتِ اللَّهِ فَإِنَّ اللَّهَ سَرِيعُ الْحِسَابِ }", "count": 1, "reference": "سورة آل عمران - الآيات 18 - 19 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_7.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10105, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ ۗ أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ ۗ تَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ * ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ * وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا وَادْعُوهُ خَوْفًا وَطَمَعًا ۚ إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِّنَ الْمُحْسِنِين }", "count": 1, "reference": "سورة الاعراف - الآيات 54 - 56 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_8.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10106, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لا تُرْجَعُونَ * فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ لا إِلَهَ إِلا هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ * وَمَن يَدْعُ مَعَ اللَّهِ إِلَٰهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ ۚ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ * وَقُل رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّاحِمِينَ }", "count": 1, "reference": "سورة المؤمنون - الآيات 115 - 118 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_9.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10107, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ * فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ * فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ * وَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ * قَالُوا آمَنَّا بِرَبِّ الْعَالَمِين * رَبِّ مُوسَىٰ وَهَارُونَ }", "count": 1, "reference": "سورة الاعراف - الآيات 117 - 122 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_10.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10108, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { وَالصَّافَّاتِ صَفًّا * فَالزَّاجِرَاتِ زَجْرًا * فَالتَّالِيَاتِ ذِكْرًا * إِنَّ إِلَهَكُمْ لَوَاحِدٌ * رَبُّ السَّمَاوَاتِ وَالأرْضِ وَمَا بَيْنَهُمَا وَرَبُّ الْمَشَارِقِ * إِنَّا زَيَّنَّا السَّمَاءَ الدُّنْيَا بِزِينَةٍ الْكَوَاكِبِ * وَحِفْظًا مِنْ كُلِّ شَيْطَانٍ مَارِدٍ * لا يَسَّمَّعُونَ إِلَى الْمَلأ الأعْلَى وَيُقْذَفُونَ مِنْ كُلِّ جَانِبٍ * دُحُورًا وَلَهُمْ عَذَابٌ وَاصِبٌ * إِلا مَنْ خَطِفَ الْخَطْفَةَ فَأَتْبَعَهُ شِهَابٌ ثَاقِبٌ }", "count": 1, "reference": "سورة الصافات - الآيات 1 - 10 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_11.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10109, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِنْ الْجِنِّ يَسْتَمِعُونَ الْقُرْءانَ فَلَمَّا حَضَرُوهُ قَالُوا أَنْصِتُوا فَلَمَّا قُضِىَ وَلَّوْا إِلَى قَوْمِهِمْ مُنْذِرِينَ * قَالُوا يَاقَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنْزِلَ مِنْ بَعْدِ مُوسَى مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ يَهْدِى إِلَى الْحَقِّ وَإِلَى طَرِيقٍ مُسْتَقِيمٍ * يَاقَوْمَنَا أَجِيبُوا دَاعِي اللَّهِ وَءامِنُوا بِهِ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُجِرْكُمْ مِنْ عَذَابٍ أَلِيمٍ }", "count": 1, "reference": "سورة الاحقاف - الآيات 29 - 31 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_12.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10110, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { يَا مَعْشَرَ الْجِنِّ وَالْإِنسِ إِنِ اسْتَطَعْتُمْ أَن تَنفُذُوا مِنْ أَقْطَارِ السَّمَاوَاتِ وَالْأَرْضِ فَانفُذُوا ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَانٍ * فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ * يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ * فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ }", "count": 1, "reference": "سورة الرحمن - الآيات 33 - 36 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_13.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10111, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { لَوْ أَنْزَلْنَا هَذَا الْقُرْءانَ عَلَى جَبَلٍ لَرَأَيْتَهُ خَاشِعًا مُتَصَدِّعًا مِنْ خَشْيَةِ اللَّهِ وَتِلْكَ الأمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ * هُوَ اللَّهُ الَّذِى لا إِلَهَ إِلا هُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ هُوَ الرَّحْمَنُ الرَّحِيمُ * هُوَ اللَّهُ الَّذِى لا إِلَهَ إِلا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ * هو الله الخالق البارئ المصور له الأسماء الحسنى يُسَبِّحُ لَهُ مَا فِى السَّمَاوَاتِ وَالأرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ }", "count": 1, "reference": "سورة الحشر - الآيات 21 - 24 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/ruqya_14.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10112, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ }", "count": 3, "reference": "سورة الاخلاص .", "times": "3 مرة", "audio": "assets/audio/azkari/ruqya_15.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10113, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِنْ شَرِّ مَا خَلَقَ * وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِنْ شَرِّ النَّفَّاثَاتِ فِى الْعُقَدِ * وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ }", "count": 3, "reference": "سورة الفلق .", "times": "3 مرة", "audio": "assets/audio/azkari/ruqya_16.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10114, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ * مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِى صُدُورِ النَّاسِ * مِنْ الْجِنَّةِ وَالنَّاسِ }", "count": 3, "reference": "سورة الناس .", "times": "3 مرة", "audio": "assets/audio/azkari/ruqya_17.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10115, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ * الرَّحْمَنِ الرَّحِيمِ * مَالِكِ يَوْمِ الدِّينِ * إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ * اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ * صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ و َلَا الضَّالِّين }", "count": 10, "reference": "سورة الفاتحة .", "times": "10 مرة", "audio": "assets/audio/azkari/ruqya_1.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10116, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { اللَّهُ لا إِلَهَ إِلا هُوَ الْحَىُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ مَا فِى السَّمَاوَاتِ وَمَا فِى الأرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَىْءٍ مِنْ عِلْمِهِ إِلا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِىُّ الْعَظِيمُ }", "count": 9, "reference": "سورة البقرة - الآية 255 .", "times": "9 مرة", "audio": "assets/audio/azkari/ruqya_5.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10117, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ * لَمْ يَلِدْ وَلَمْ يُولَدْ * وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ }", "count": 10, "reference": "سورة الاخلاص .", "times": "10 مرة", "audio": "assets/audio/azkari/ruqya_15.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10118, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ * مِنْ شَرِّ مَا خَلَقَ * وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ * وَمِنْ شَرِّ النَّفَّاثَاتِ فِى الْعُقَدِ * وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ }", "count": 10, "reference": "سورة الفلق .", "times": "10 مرة", "audio": "assets/audio/azkari/ruqya_16.mp3", "sourceCategory": "الرقية الشرعية"}, {"id": 10119, "text": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ { قُلْ أَعُوذُ بِرَبِّ النَّاسِ * مَلِكِ النَّاسِ * إِلَهِ النَّاسِ * مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ * الَّذِي يُوَسْوِسُ فِى صُدُورِ النَّاسِ * مِنْ الْجِنَّةِ وَالنَّاسِ }", "count": 10, "reference": "سورة الناس .", "times": "10 مرة", "audio": "assets/audio/azkari/ruqya_17.mp3", "sourceCategory": "الرقية الشرعية"}], "azkari_12": [{"id": 10120, "text": "بسم الله ولجنا ، وبسم الله خرجنا ، وعلى ربنا توكلنا ، ثم ليسلم على أهله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/manzel_dukhool.mp3", "sourceCategory": "الذكر عند الدخول للمنزل"}], "azkari_13": [{"id": 10121, "text": "بسم الله ، توكَّلْتُ على الله ، ولا حَوْلَ ولا قُوةَ إلا بالله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/mnzel_khurooj_1.mp3", "sourceCategory": "الذكر عند الخروج من المنزل"}, {"id": 10122, "text": "اللهُمَ إني أعُوذُ بِكَ أن أَضلَّ ، أوْ أُضَلَّ ، أَوْ أزلَّ ، أو أُزلَّ ، أوْ أظلِم ، أوْ أُظْلَم ، أوْ أَجْهَلَ ، أوْ يُجْهَلَ عَلَيَّ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/mnzel_khurooj_2.mp3", "sourceCategory": "الذكر عند الخروج من المنزل"}], "azkari_14": [{"id": 10123, "text": "دعاء لبس الثوب : الحمدُ للهِ الّذي كَساني هذا الثّوب وَرَزَقَنيه مِنْ غَـيـْرِ حَولٍ مِنّي وَلا قـوّة .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_003_2_part.mp3", "sourceCategory": "أدعية لبس وخلع الثوب"}, {"id": 10124, "text": "دعاء لبس الثوب الجديد : اللَّهُمَّ لَكَ الحَمْدُ أَنْتَ كَسَوتَنِيه ، أسْألك مِنْ خَيرِهِ وخَيْرَ ما صُنع لَهُ ، وأعُوذُ بِكَ مِنْ شرِّه وشَرَّ ما صُنِعَ لَهُ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_004_2_part.mp3", "sourceCategory": "أدعية لبس وخلع الثوب"}, {"id": 10125, "text": "ما يقول إذا وضع الثوب : بِسم الله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_006_2_part.mp3", "sourceCategory": "أدعية لبس وخلع الثوب"}], "azkari_15": [{"id": 10126, "text": "دعاء دخول الخلاء : بسم الله ، اللهُمَّ إنّي أعُوذُ بِكَ مِنَ الخُبْثِ والخبائِثِ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_007_2_part.mp3", "sourceCategory": "أدعية الدخول و الخروج من الخلاء"}, {"id": 10127, "text": "دعاء الخروج من الخلاء : غُفْرانَكَ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_008_2_part.mp3", "sourceCategory": "أدعية الدخول و الخروج من الخلاء"}], "azkari_16": [{"id": 10128, "text": "الذكر قبل الوضوء : بسم الله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_009_2_part.mp3", "sourceCategory": "أذكار الوضوء"}, {"id": 10129, "text": "الذكر بعد الفراغ من الوضوء (1) : أَشْهَدُ أَنْ لا إِلَـهَ إِلاّ اللهُ وَحْدَهُ لا شَريـكَ لَـهُ وَأَشْهَدُ أَنَّ مُحَمّـداً عَبْـدُهُ وَرَسـولُـه .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_010_2_1_part.mp3", "sourceCategory": "أذكار الوضوء"}, {"id": 10130, "text": "الذكر بعد الفراغ من الوضوء (2) : اللّهُـمَّ اجْعَلنـي مِنَ التَّـوّابينَ وَاجْعَـلْني مِنَ المتَطَهّـرين .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_010_2_2_part.mp3", "sourceCategory": "أذكار الوضوء"}, {"id": 10131, "text": "الذكر بعد الفراغ من الوضوء (3) : سبحانك اللهم وبحمدك , أشهد أن لا إله إلا أنت , أستغفرك وأتوب إليك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_010_2_3_part.mp3", "sourceCategory": "أذكار الوضوء"}], "azkari_17": [{"id": 10132, "text": "دعاء الذهاب الى المسجد : اللهم اجعل في قلبي نوراً ، وفي لساني نوراً ، وفي سمعي نوراً ، وفي بصري نوراً ، ومن فوقي نوراً ، ومن تحتي نوراً ، وعن يميني نوراً ، وعن شمالي نوراً ، ومن أمامي نوراً ، ومن خلفي نوراً ، و اجعل في نفسي نوراً ، وأعظم لي نوراً ، وعظم لي نوراً ، واجعل لي نوراً ، واجعلني نوراً ، اللهم أعطني نوراً ، واجعل في عصبي نوراً ، وفي لحمي نوراً ، وفي دمي نوراً ، وفي شعري نوراً ، وفي بشري نوراً . اللهم اجعل لي نوراً في قبري . ونوراً في عظامي وزدني نوراً ، وزدني نوراً ، وزدني نوراً ، وهب لي نوراً على نوراً .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_013_2_part.mp3", "sourceCategory": "أدعية الذهاب والدخول الى المسجد"}, {"id": 10133, "text": "دعاء دخول المسجد : أعوذ بالله العظيم ، وبوجهه الكريم ، وسلطانه القديم ، من الشيطان الرجيم ، بسم الله ، والصلاة والسلام على رسول الله ، اللهم افتح لي أبواب رحمتك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_014_2_part.mp3", "sourceCategory": "أدعية الذهاب والدخول الى المسجد"}], "azkari_18": [{"id": 10134, "text": "بسم الله ، والصلاة والسلام على رسول الله ، اللهم إني أسألك من فضلك ، اللهم اعصمني من الشيطان الرجيم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_015_2_part.mp3", "sourceCategory": "دعاء الخروج من المسجد"}], "azkari_19": [{"id": 10135, "text": "يقول مثل ما يقول المؤذن إلا في حي على الصلاة ، وحي على الفلاح فيقول : لا حول ولا قوة إلا بالله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_016_2_1_part.mp3", "sourceCategory": "أذكار الأذان"}, {"id": 10136, "text": "يقول : وأنا أشهد أن لا إله إلا الله ، وحده لا شريك له ، وأن محمداً عبده ورسوله ، رضيت بالله رباً ، وبمحمد رسولاً وبالإسلام ديناً . يقول ذلك عقب تشهد المؤذن .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_016_2_2_part.mp3", "sourceCategory": "أذكار الأذان"}, {"id": 10137, "text": "يصلي على النبي صلى الله عليه وسلم بعد فراغه من إجابة المؤذن .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_016_2_3_part.mp3", "sourceCategory": "أذكار الأذان"}, {"id": 10138, "text": "اللهم رب هذه الدعوة التامة ، والصلاة القائمة ، آت محمداً الوسيلة والفضيلة ، وأبعثه مقاماً محموداً الذي وعدته ، إنك لا تخلف الميعاد .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_016_2_4_part.mp3", "sourceCategory": "أذكار الأذان"}, {"id": 10139, "text": "يدعو لنفسه بين الأذان والإقامة فإن الدعاء حينئذٍ لا يرد .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_016_2_5_part.mp3", "sourceCategory": "أذكار الأذان"}], "azkari_20": [{"id": 10140, "text": "قال جابر بن عبد الله رضي الله عنهما : كان رسول الله صلى الله عليه وسلم ، يُعلمنا الاستخارة في الأمور كلها ، كما يعلمُنا السورة من القرآن ، يقول : إذا هم أحدكم بالأمر فليركع ركعتين من غير الفريضة ، ثم ليقل : اللهم إني أستخيرك بعلمك ، وأستقدرك بقدرتك ، وأسألك من فضلك العظيم فإنك تقدِرُ ولا أقدِرُ ، وتعلم ولا أعلم ، وأنت علام الغيوب ، اللهم إن كنت تعلم أن هذا الأمر - يسمي حاجته - خير لي في ديني ومعاشي وعاقبة أمري - أو قال : عاجلة وآجله - فاقدره لي ويسره لي ، ثم بارك لي فيه ، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري - أو قال : عاجله وآجله - فاصرفه عني واصرفني عنه ، واقدر لي الخير حيث كان ، ثم ارضني به . وما ندم من استخار الخالق ، وشاور المخلوقين المؤمنين وتثبت في أمره ، فقد قال سبحانه { وَشَاوِرْهُمْ فِي الأَمْرِ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى اللّهِ }", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_027_2_part.mp3", "sourceCategory": "دعاء صلاة الاستخارة"}], "azkari_21": [{"id": 10141, "text": "دعاء قنوت الوتر (1) : اللهم اهدني فيمن هديت ، وعافني فيمن عافيت ، وتولني فيمن توليت ، وبارك لي فيما أعطيت ، وقني شر ما قضيت ، فإنك تقضي ولا يقضى عليك ، إنه لا يذل من واليت ، ولا يعز من عاديت ، تباركت ربنا وتعاليت .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_033_2_1_part.mp3", "sourceCategory": "دعاء قنوت الوتر"}, {"id": 10142, "text": "دعاء قنوت الوتر (2) : اللهم إني أعوذ برضاك من سخطك وبمعافاتك من عقوبتك ، وأعوذ بك منك لا أحصي ثناء عليك ، أنت كما أثنيت على نفسك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_033_2_2_part.mp3", "sourceCategory": "دعاء قنوت الوتر"}, {"id": 10143, "text": "دعاء قنوت الوتر (3) : اللهم إياك نعبد ، ولك نُصلي ونسجد ، وإليك نسعى ونحفدُ ، نرجُو رحمتك ، ونخشى عذابك ، إن عذابك بالكافرين ملحق ، اللهم إنا نستعينك ، ونستغفرك ، ونثني عليك الخير ، ولا نكفرك ، ونؤمن بك ونخضع لك ، ونخلع من يكفرك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_033_2_3_part.mp3", "sourceCategory": "دعاء قنوت الوتر"}, {"id": 10144, "text": "الذكر عقب السلام من الوتر : سبحان الملك القدوس ، ( ثلاث مرات والثالثة يجهر بها ويمد بها صوته ) رب الملائكة والروح .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_034_2_part.mp3", "sourceCategory": "دعاء قنوت الوتر"}], "azkari_22": [{"id": 10145, "text": "اللهم إني عبدك ابن عبدك ابن أمتك ناصيتي بيدك ، ماضِ في حكمك ، عدل في قضاؤك ، أسألك بكل اسم هو لك سميت به نفسك أو أنزلته في كتابك ، أو علمته أحداً من خلقك أو استأثرت به في علم الغيب عندك أن تجعل القرآن ربيع قلبي ، ونور صدري ، وجلاء حزني وذهاب همي .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_035_2_1_part.mp3", "sourceCategory": "دعاء الهم والحزن"}, {"id": 10146, "text": "اللهم إني أعوذ بك من الهم والحزن ، والعجز والكسل ، والبخل والجبن ، وضلع الدين وغلبة الرجال .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_035_2_2_part.mp3", "sourceCategory": "دعاء الهم والحزن"}], "azkari_23": [{"id": 10147, "text": "لا إله إلا الله العظيم الحليم ، لا إله إلا الله رب العرش العظيم ، لا إله إلا الله رب السموات ورب الارض ورب العرش الكريم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_036_2_1_part.mp3", "sourceCategory": "دعاء الكرب"}, {"id": 10148, "text": "اللهم رحمتك أرجو فلا تكلني إلى نفسي طرفة عين ، وأصلح لي شأني كله لا إله إلا أنت .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_036_2_2_part.mp3", "sourceCategory": "دعاء الكرب"}, {"id": 10149, "text": "لا إله إلا أنت سبحانك إني كنت من الظالمين .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_036_2_3_part.mp3", "sourceCategory": "دعاء الكرب"}, {"id": 10150, "text": "الله ، الله ربي لا أشرك به شيئاً .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_036_2_4_part.mp3", "sourceCategory": "دعاء الكرب"}], "azkari_24": [{"id": 10151, "text": "أعوذ بالله من الشيطان الرجيم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_083_2_part.mp3", "sourceCategory": "دعاء الغضب"}], "azkari_25": [{"id": 10152, "text": "عن ابن عمر قال : كان يعد لرسول الله صلى الله عليه وسلم في المجلس الواحد مائة مرة من قبل أن يقوم رب اغفر لي وتب علي إنك أنت التواب الغفور .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_085_2_part.mp3", "sourceCategory": "ما يقال في المجلس"}], "azkari_26": [{"id": 10153, "text": "سبحانك اللهم وبحمدك ، أشهد أن لا إله إلا أنت ، أستغفرك وأتوب إليك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_086_2_part.mp3", "sourceCategory": "كفارة المجلس"}], "azkari_27": [{"id": 10154, "text": "لا إله إلا الله وحده لا شريك له ، له الملك وله الحمد ، يُحيي ويُميت ، وهو حي لا يموت ، بيده الخير وهو على كل شئ قدير .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_099_2_part.mp3", "sourceCategory": "دعاء دخول السوق"}], "azkari_28": [{"id": 10155, "text": "ذَهبَ الظَّمأُ ، وابتلَّت العروقُ ، وثَبَتَ الأجرُ إنْ شاء الله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_069_2_1_part.mp3", "sourceCategory": "الدعاء عند إفطار الصائم"}, {"id": 10156, "text": "اللهم إني أسألك برحمتك التي وسعت كل شيءٍ أن تغفر لي .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_069_2_2_part.mp3", "sourceCategory": "الدعاء عند إفطار الصائم"}], "azkari_29": [{"id": 10157, "text": "بسم الله ، اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا .", "count": 1, "reference": "عَنْ ابْنِ عَبَّاسٍ رضي الله عنهما قَالَ : أن رسول الله صلى الله عليه وسلم قال :  لو أن أحدكم إذا أتى أهله قال : باسم الله ، اللهم جنبنا الشيطان ، وجنب الشيطان ما رزقتنا ، فإنه إن يقدر بينهما ولد لم يضره الشيطان أبداً   .", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_082_2_part.mp3", "sourceCategory": "الدعاء قبل إتيان الزوجة"}], "azkari_30": [{"id": 10158, "text": "اللهم إني أعوذ بك أن أشرك بك وأنا أعلم ، وأستغفرك لما لا أعلم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_093_2_part.mp3", "sourceCategory": "دعاء الخوف من الشرك"}], "azkari_31": [{"id": 10159, "text": "الله أكبر ، اللهم أهلِه علينا بالأمن والإيمان ، والسلامة والإسلام ، والتوفيق لما تحب ربنا وترضى ، ربنا وربك الله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_068_2_part.mp3", "sourceCategory": "دعاء رؤية الهلال"}], "azkari_32": [{"id": 10160, "text": "اللهم اكفني بحلالك عن حرامك ، وأغنني بفضلك عمن سواك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_042_2_1_part.mp3", "sourceCategory": "دعاء قضاء الدين"}, {"id": 10161, "text": "اللهم إني أعوذ بك من الهم والحزن ، والعجز والكسل ، والبخل والجبن ، وضلع الدين وغلبة الرجال .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_042_2_2_part.mp3", "sourceCategory": "دعاء قضاء الدين"}], "azkari_33": [{"id": 10162, "text": "يستعيذ بالله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_041_2_1_part.mp3", "sourceCategory": "دعاء من أصابه شك في الإيمان"}, {"id": 10163, "text": "ينتهي عما شك فيه .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_041_2_2_part.mp3", "sourceCategory": "دعاء من أصابه شك في الإيمان"}, {"id": 10164, "text": "يقول آمنت بالله ورسله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_041_2_3_part.mp3", "sourceCategory": "دعاء من أصابه شك في الإيمان"}, {"id": 10165, "text": "يقرأ قوله تعالى { هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ }", "count": 1, "reference": "سورة الحديد - الآية 3 .", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_041_2_4_part.mp3", "sourceCategory": "دعاء من أصابه شك في الإيمان"}], "azkari_34": [{"id": 10166, "text": "اللهم لا سهل إلا ما جعلته سهلاً ، وأنت تجعل الحزن إذا شئت سهلاً .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_044_2_part.mp3", "sourceCategory": "دعاء من استصعب عليه أمر"}], "azkari_35": [{"id": 10167, "text": "قال صلى الله عليه وسلم : ما من عبدٍ يذنب ذنباً فيحسن الطهور ، ثم يقوم فيصلي ركعتين ، ثم يستغفر الله إلا غفر الله لهُ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_045_2_part.mp3", "sourceCategory": "ما يقول ويفعل من أذنب ذنبا"}], "azkari_36": [{"id": 10168, "text": "ينفث عن يساره .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/sound_032_2_1_part.mp3", "sourceCategory": "ما يفعل من رأى الرؤيا أو الحلم"}, {"id": 10169, "text": "يستعيذ بالله من الشيطان ومن شر ما رأى .", "count": 3, "reference": "من أذكار المسلم", "times": "3 مرة", "audio": "assets/audio/azkari/sound_032_2_2_part.mp3", "sourceCategory": "ما يفعل من رأى الرؤيا أو الحلم"}, {"id": 10170, "text": "لا يحدث بها أحداً ويتحول عن جنبه الذي كان عليه ويقوم يصلي إن أراد ذلك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_032_2_3_part.mp3", "sourceCategory": "ما يفعل من رأى الرؤيا أو الحلم"}], "azkari_37": [{"id": 10171, "text": "أعوذ بكلمات الله التَّامَّة من غضبه وعقابه ، وشر عباده ، ومن همزات الشياطين وأنْ يحضرون .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_031_2_part.mp3", "sourceCategory": "دعاء الفزع في النوم ومن بلي بالوحشة"}], "azkari_38": [{"id": 10172, "text": "لا إله إلا الله الواحد القهار ، ربُّ السموات والأرض وما بينهما العزيز الغفار .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/sound_030_2_part.mp3", "sourceCategory": "الدعاء إذا تقلب ليلا"}], "azkari_39": [{"id": 10173, "text": "اللّهُمَّ أسْقِـنا غَيْـثاً مُغيـثاً مَريئاً مَريـعاً ، نافِعـاً غَيْـرَ ضار ، عاجِـلاً غَـيْرَ آجِل .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/alestska_part1.mp3", "sourceCategory": "أذكار الاستسقاء"}, {"id": 10174, "text": "اللّهُمَّ أغِثْنـا ، اللّهُمَّ أغِثْنـا اللّهُمَّ أغِثْنـا .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/alestska_part2.mp3", "sourceCategory": "أذكار الاستسقاء"}, {"id": 10175, "text": "اللّهُمَّ اسْقِ عِبادَكَ ، وَبَهـائِمَك ، وَانْشُـرْ رَحْمَـتَكَ ، وَأَحْيِي بَلَـدَكَ المَيِّـت .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/alestska_part3.mp3", "sourceCategory": "أذكار الاستسقاء"}], "azkari_40": [{"id": 10176, "text": "أللّـهُمَّ رَبَّ السَّـمواتِ السّـبْعِ وَما أَظْلَلَـن ، وَرَبَّ الأَراضيـنَ السّـبْعِ وَما أقْلَلْـن ، وَرَبَّ الشَّيـاطينِ وَما أَضْلَلْـن ، وَرَبَّ الرِّياحِ وَما ذَرَيْـن ، أَسْـأَلُـكَ خَيْـرَ هذهِ الْقَـرْيَةِ وَخَيْـرَ أَهْلِـها ، وَخَيْـرَ ما فيها ، وَأَعـوذُ بِكَ مِنْ شَـرِّها وَشَـرِّ أَهْلِـها ، وَشَـرِّ ما فيها .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/dkholalqrya_part.mp3", "sourceCategory": "دعاء دخول القرية او البلدة"}], "azkari_41": [{"id": 10177, "text": "الدعاء عند إغماض الميت : اللهُـمِّ اغْفِـرْ لِـ - فلان باسـمه - وَارْفَعْ دَرَجَتَـهُ في المَهْـدِييـن ، وَاخْـلُفْـهُ في عَقِـبِهِ في الغابِـرين ، وَاغْفِـرْ لَنـا وَلَـهُ يا رَبَّ العـالَمـين ، وَافْسَـحْ لَهُ في قَبْـرِهِ وَنَـوِّرْ لَهُ فيه .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/agmadalmayt_part.mp3", "sourceCategory": "الدعاء للميت"}, {"id": 10178, "text": "الدعاء للميت في الصلاة عليه (1) : اللهُـمِّ اغْفِـرْ لَهُ وَارْحَمْـه ، وَعافِهِ وَاعْفُ عَنْـه ، وَأَكْـرِمْ نُزُلَـه ، وَوَسِّـعْ مُدْخَـلَه ، وَاغْسِلْـهُ بِالْمـاءِ وَالثَّـلْجِ وَالْبَـرَدْ ، وَنَقِّـهِ مِنَ الْخطـايا كَما نَـقّيْتَ الـثَّوْبَ الأَبْيَـضَ مِنَ الدَّنَـسْ ، وَأَبْـدِلْهُ داراً خَـيْراً مِنْ دارِه ، وَأَهْلاً خَـيْراً مِنْ أَهْلِـه ، وَزَوْجَـاً خَـيْراً مِنْ زَوْجِه ، وَأَدْخِـلْهُ الْجَـنَّة ، وَأَعِـذْهُ مِنْ عَذابِ القَـبْر وَعَذابِ النّـار .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/slah_alal_mayt_part1.mp3", "sourceCategory": "الدعاء للميت"}, {"id": 10179, "text": "الدعاء للميت في الصلاة عليه (2) : اللهُـمِّ اغْفِـرْ لِحَيِّـنا وَمَيِّتِـنا ، وَشـاهِدِنا وَغائِبِـنا ، وَصَغيـرِنا وَكَبيـرِنا ، وَذَكَـرِنا وَأُنْثـانا . اللهُـمِّ مَنْ أَحْيَيْـتَهُ مِنّا فَأَحْيِـهِ عَلى الإِسْلام ، وَمَنْ تَوَفَّـيْتَهُ مِنّا فَتَوَفَّـهُ عَلى الإِيـمان ، اللهُـمِّ لا تَحْـرِمْنـا أَجْـرَه ، وَلا تُضِـلَّنا بَعْـدَه .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/slah_alal_mayt_part2.mp3", "sourceCategory": "الدعاء للميت"}, {"id": 10180, "text": "الدعاء للميت في الصلاة عليه (3) : اللهُـمِّ إِنَّ - فُلانَ بْنَ فُلانٍ - في ذِمَّـتِك ، وَحَبْـلِ جِـوارِك ، فَقِـهِ مِنْ فِتْـنَةِ الْقَـبْرِ وَعَذابِ النّـار ، وَأَنْتَ أَهْلُ الْوَفـاءِ وَالْـحَقِّ ، فَاغْفِـرْ لَهُ وَارْحَمْـهُ ، إِنَّكَ أَنْتَ الغَـفورُ الـرَّحيم .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/slah_alal_mayt_part3.mp3", "sourceCategory": "الدعاء للميت"}, {"id": 10181, "text": "الدعاء للميت في الصلاة عليه (4) : اللهُـمِّ عَبْـدُكَ وَابْنُ أَمَـتِك ، احْتـاجَ إِلى رَحْمَـتِك ، وَأَنْتَ غَنِـيٌّ عَنْ عَذابِـه ، إِنْ كانَ مُحْـسِناً فَزِدْ في حَسَـناتِه ، وَإِنْ كانَ مُسـيئاً فَتَـجاوَزْ عَنْـه .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/slah_alal_mayt_part4.mp3", "sourceCategory": "الدعاء للميت"}, {"id": 10182, "text": "الدعاء عند إدخال الميت القبر : بِسْـمِ اللهِ وَعَلـى سُـنَّةِ رَسـولِ الله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/dkhol_almayt_alhbr_part.mp3", "sourceCategory": "الدعاء للميت"}, {"id": 10183, "text": "الدعاء بعد دفن الميت : اللهُـمِّ اغْفِـرْ لَهُ ، اللهُـمِّ ثَبّتْهُ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/dfn_almayt_part.mp3", "sourceCategory": "الدعاء للميت"}], "azkari_42": [{"id": 10184, "text": "إِنَّ للهِ ما أَخَذ ، وَلَهُ ما أَعْـطـى ، وَكُـلُّ شَيءٍ عِنْـدَهُ بِأَجَلٍ مُسَـمَّى . فَلْتَصْـبِر وَلْتَحْـتَسِب .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/altazyeh_part1.mp3", "sourceCategory": "أذكار التعزية"}, {"id": 10185, "text": "أَعْظَـمَ اللهُ أَجْـرَك ، وَأَحْسَـنَ عَـزاءَك ، وَغَفَـرَ لِمَـيِّتِك .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/altazyeh_part2.mp3", "sourceCategory": "أذكار التعزية"}], "azkari_43": [{"id": 10186, "text": "السَّلَامُ عَلَيْكُمْ أهْلَ الدِّيَارِ ، مِنَ الـمُؤْمِنِينَ ، والـمُسْلِمِينَ ، وَإنَّا إنْ شَاءَ اللَّهُ بِكُمْ لاحِقُونَ [ وَيَرْحَمُ اللَّهُ الـمُستَقْدِمينَ مِنَّا والـمُستأخِرينَ ] أسألُ اللَّهَ لنَا وَلَكُمُ العَافِيَةَ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/zyart_alkboor_part.mp3", "sourceCategory": "دعاء زيارة القبور"}], "azkari_44": [{"id": 10187, "text": "اللَّهُمَّ اغْفِرْ لِي وارْحَمْنِي وأَلْـحِقْنِي بالرَّفِيقِ الأعْلَى .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/almreed_part1.mp3", "sourceCategory": "دعاء المريض الذي يئس من حياته"}, {"id": 10188, "text": "جعل النبي صلى الله عليه وسلم عند موته يدخل يديه في الماء فيمسح بهما وجههُ ويقول : لا إله إلا الله ، إن للموت لسكرات .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/almreed_part2.mp3", "sourceCategory": "دعاء المريض الذي يئس من حياته"}, {"id": 10189, "text": "لا إله إلا الله والله أكبر ، لا إله إلا الله وحده ، لا إله إلا الله وحده لا شريك لهُ ، لا إله إلا الله لهُ الملك ولهُ الحمد ، لا إله إلا الله ولا حول ولا قوة إلا بالله .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/almreed_part3.mp3", "sourceCategory": "دعاء المريض الذي يئس من حياته"}], "azkari_45": [{"id": 10190, "text": "ضَعْ يَدَكَ عَلَى الَّذِي تَأَلَّمَ مِنْ جَسَدِكَ وَقُلْ : بِاسْمِ اللَّهِ ، ثَلَاثًا ، وَقُلْ سَبْعَ مَرَّاتٍ : أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/wjaa_part.mp3", "sourceCategory": "ما يقول من أحس وجعا في جسده"}], "azkari_46": [{"id": 10191, "text": "اللَّهُمَّ مُنْزِلَ الكِتَابِ سَريعَ الحِسابِ اهْزِمَ الأَحْزَابَ اللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ .", "count": 1, "reference": "من أذكار المسلم", "times": "مرة واحدة", "audio": "assets/audio/azkari/alaado_part.mp3", "sourceCategory": "الدعاء على العدو"}]};
